<template><section class="message-page"><div class="message-head"><div><span>INBOX</span><h2>消息中心</h2><p>预约、改期、取消和退款处理结果会显示在这里。</p></div><div class="message-actions"><el-button text @click="readAll">全部已读</el-button><el-button @click="load" :loading="loading">刷新</el-button></div></div><el-empty v-if="!loading&&!items.length" description="暂无消息"/><div v-for="item in items" :key="item.id" class="message-item" :class="{unread:!item.is_read}" @click="read(item)"><div><el-tag size="small" :type="item.is_read?'info':'success'">{{item.is_read?'已读':'未读'}}</el-tag><strong>{{item.title}}</strong><el-tag v-if="item.message_type" size="small" effect="plain">{{typeLabel(item.message_type)}}</el-tag></div><p>{{item.content}}</p><time>{{item.created_at}}</time></div><el-pagination class="message-pager" layout="total, prev, pager, next" :total="total" :page-size="20" v-model:current-page="page" @current-change="load"/></section></template>
<script setup>
import {ref,onMounted,getCurrentInstance} from 'vue'
import {useRouter} from 'vue-router'
const ctx=getCurrentInstance().appContext.config.globalProperties,router=useRouter(),items=ref([]),loading=ref(false),page=ref(1),total=ref(0)
const labels={booking:'预约',change:'改期',cancel:'取消',refund:'退款',delivery:'交付'}
function typeLabel(v){return v.includes('refund')?'退款':v.includes('change')?'预约变更':v.includes('photo')||v.includes('delivery')?'照片交付':v.includes('booking')?'预约':labels[v]||'系统'}
async function load(){loading.value=true;try{const r=await ctx.$http.get('sheyingshiyuyue/messages',{params:{page:page.value,limit:20}});items.value=r.data.data||[];total.value=r.data.total||0}finally{loading.value=false}}
async function read(item){if(!item.is_read){await ctx.$http.post('sheyingshiyuyue/messages/read/'+item.id);item.is_read=1;window.dispatchEvent(new Event('huahai-messages-changed'))}if(item.booking_id)router.push({path:'/index/sheyingshiyuyueDetail',query:{id:item.booking_id,centerType:'1'}})}
async function readAll(){await ctx.$http.post('sheyingshiyuyue/messages/read-all');items.value.forEach(x=>x.is_read=1);window.dispatchEvent(new Event('huahai-messages-changed'))} onMounted(load)
</script><style scoped>.message-pager{justify-content:center;margin-top:24px}.message-page{max-width:900px;margin:0 auto;padding:36px 0}.message-head{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:1px solid #e5eade;padding-bottom:20px;margin-bottom:20px}.message-actions{display:flex;gap:8px}.message-head span{font-size:11px;letter-spacing:.16em;color:#82907f}.message-head h2{margin:8px 0 4px;color:#294a3b}.message-head p{margin:0;color:#849083;font-size:13px}.message-item{padding:18px 4px;border-bottom:1px solid #e6ebe1;cursor:pointer}.message-item>div{display:flex;gap:10px;align-items:center}.message-item strong{color:#3c5140}.message-item p{margin:10px 0 7px;color:#687568;line-height:1.8}.message-item time{font-size:11px;color:#9ba49a}.message-item.unread{background:#f6f8f3;padding-left:12px;border-left:3px solid #305d4c}</style>
